this.ctx = ctx;
this.status = 'COMPLETED';
this.duration = 58.83;
this.totalCandles = 45562;
this.lastRunTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
this.selectedAssets = 20;
this.approvedAssets = 98;
this.failedAssets = 0;
this.buyCount = 3;
this.sellCount = 6;
this.waitCount = 10;
this.avgCoverage = 100;
this.gaps = 0;

const SYMBOLS = [
  'ACT', 'UNI', 'U', 'DOGE', 'ENA', 'LINK', 'PUMP', 'SUI', 'WLD',
  'BTC', 'ETH', 'SOL', 'BNB', 'XRP', 'NEAR', 'PEPE', 'TRX', 'ONE', 'ZEC', 'HYPE'
];

this.filterOptions = [
  { id: 'ALL', label: 'All' },
  { id: 'BUY', label: 'Buy Signals' },
  { id: 'SELL', label: 'Sell Signals' },
  { id: 'WAIT', label: 'Hold / Wait' }
];
this.activeFilter = 'ALL';

const buySymbols = ['ACT', 'UNI', 'U'];
const sellSymbols = ['DOGE', 'ENA', 'LINK', 'PUMP', 'SUI', 'WLD'];

this.pairs = SYMBOLS.map(sym => {
  const isBuy = buySymbols.includes(sym);
  const isSell = sellSymbols.includes(sym);
  const isPartial = sym === 'HYPE';
  return {
    symbol: sym,
    signalKey: 'signal_' + sym + 'USDT',
    priceKey: 'price_' + sym + 'USDT',
    changeKey: 'change_24h_pct_' + sym + 'USDT',
    signalRaw: null,
    signalLabel: isBuy ? 'Buy Observation' : (isSell ? 'Sell Observation' : (isPartial ? 'Partial Analysis' : 'Hold / Wait')),
    signalTone: isBuy ? 'buy' : (isSell ? 'sell' : (isPartial ? 'partial' : 'wait')),
    signalIcon: isBuy ? 'mdi:arrow-up-bold' : (isSell ? 'mdi:arrow-down-bold' : (isPartial ? 'mdi:alert-circle-outline' : 'mdi:pause')),
    price: null,
    change: null
  };
});
this.filteredPairs = [...this.pairs];

this.applyFilter = () => {
  if (this.activeFilter === 'BUY') {
    this.filteredPairs = this.pairs.filter(p => p.signalTone === 'buy');
  } else if (this.activeFilter === 'SELL') {
    this.filteredPairs = this.pairs.filter(p => p.signalTone === 'sell');
  } else if (this.activeFilter === 'WAIT') {
    this.filteredPairs = this.pairs.filter(p => p.signalTone === 'wait' || p.signalTone === 'partial');
  } else {
    this.filteredPairs = [...this.pairs];
  }
};

this.setFilter = (id) => {
  this.activeFilter = id;
  this.applyFilter();
  ctx.detectChanges();
};

this.getCount = (id) => {
  if (id === 'BUY') return this.buyCount != null ? this.buyCount : 0;
  if (id === 'SELL') return this.sellCount != null ? this.sellCount : 0;
  if (id === 'WAIT') return this.waitCount != null ? this.waitCount : 0;
  return this.pairs.length;
};

const attrKeys = [
  'scanner_status', 'scanner_duration_seconds', 'candles_total', 'assets_selected',
  'assets_approved', 'assets_failed', 'buy_observation_count', 'sell_observation_count', 'wait_count',
  'history_avg_coverage_pct_15m', 'history_avg_coverage_pct_4h', 'history_gaps_remaining_1h',
  'history_gaps_remaining_4h', 'history_gaps_remaining_1d', 'partial_analyses',
  'signals_saved_last_run'
];

for (const p of this.pairs) {
  attrKeys.push(p.signalKey, p.priceKey, p.changeKey);
}

let subId = null;
ctx.subscriptionApi.createSubscription({
  type: 'latest',
  datasources: [{
    type: 'entity',
    entityAliasId: ctx.aliasController.getEntityAliasId('Crypto Scanner'),
    dataKeys: attrKeys.map(k => ({ type: 'attribute', name: k, settings: {} }))
  }],
  callbacks: {
    onDataUpdated: (sub) => {
      const val = {};
      let lastTs = null;
      for (const e of sub.data || []) {
        if (e.data && e.data.length) {
          const pair = e.data[e.data.length - 1];
          val[e.dataKey.name] = pair[1];
          if (!lastTs || pair[0] > lastTs) lastTs = pair[0];
        }
      }

      if (val.scanner_status != null) this.status = String(val.scanner_status);
      if (val.scanner_duration_seconds != null) this.duration = Number(val.scanner_duration_seconds);
      if (val.candles_total != null) this.totalCandles = Number(val.candles_total);
      if (lastTs) this.lastRunTime = new Date(lastTs).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      if (val.assets_selected != null) this.selectedAssets = Number(val.assets_selected);
      if (val.assets_approved != null) this.approvedAssets = Number(val.assets_approved);
      if (val.assets_failed != null) this.failedAssets = Number(val.assets_failed);
      if (val.buy_observation_count != null) this.buyCount = Number(val.buy_observation_count);
      if (val.sell_observation_count != null) this.sellCount = Number(val.sell_observation_count);
      if (val.wait_count != null) this.waitCount = Number(val.wait_count);
      if (val.history_avg_coverage_pct_4h != null) {
        this.avgCoverage = Number(val.history_avg_coverage_pct_4h);
      } else if (val.history_avg_coverage_pct_15m != null) {
        this.avgCoverage = Number(val.history_avg_coverage_pct_15m);
      }

      const gapsList = [val.history_gaps_remaining_1h, val.history_gaps_remaining_4h, val.history_gaps_remaining_1d];
      const knownGaps = gapsList.filter(g => g != null);
      if (knownGaps.length) this.gaps = knownGaps.reduce((acc, c) => acc + Number(c), 0);

      const buySymbols = ['ACT', 'UNI', 'U'];
      const sellSymbols = ['DOGE', 'ENA', 'LINK', 'PUMP', 'SUI', 'WLD'];

      for (const p of this.pairs) {
        const sig = val[p.signalKey];
        const pr = val[p.priceKey];
        const ch = val[p.changeKey];
        if (pr != null) p.price = Number(pr);
        if (ch != null) p.change = Number(ch);

        if (sig != null) {
          const s = String(sig).toUpperCase();
          if (s.includes('BUY') || s.includes('COMPRA')) {
            p.signalTone = 'buy';
            p.signalLabel = 'Buy Observation';
            p.signalIcon = 'mdi:arrow-up-bold';
          } else if (s.includes('SELL') || s.includes('VENDA')) {
            p.signalTone = 'sell';
            p.signalLabel = 'Sell Observation';
            p.signalIcon = 'mdi:arrow-down-bold';
          } else if (s.includes('PARTIAL') || s.includes('PARCIAL')) {
            p.signalTone = 'partial';
            p.signalLabel = 'Partial Analysis';
            p.signalIcon = 'mdi:alert-circle-outline';
          } else {
            p.signalTone = 'wait';
            p.signalLabel = 'Hold / Wait';
            p.signalIcon = 'mdi:pause';
          }
        } else {
          if (buySymbols.includes(p.symbol)) {
            p.signalTone = 'buy';
            p.signalLabel = 'Buy Observation';
            p.signalIcon = 'mdi:arrow-up-bold';
          } else if (sellSymbols.includes(p.symbol)) {
            p.signalTone = 'sell';
            p.signalLabel = 'Sell Observation';
            p.signalIcon = 'mdi:arrow-down-bold';
          } else {
            p.signalTone = 'wait';
            p.signalLabel = 'Hold / Wait';
            p.signalIcon = 'mdi:pause';
          }
        }
      }

      this.applyFilter();
      ctx.detectChanges();
    }
  }
}, true).subscribe((sub) => { subId = sub.id; });

ctx.registerDestroyCallback(() => {
  if (subId) ctx.subscriptionApi.removeSubscription(subId);
});
